def minimum_k(s, k):
    sorted_by_value = sorted(enumerate(s), key=lambda x: x[1])

    char_dict = {'a': list(), 'b': list(), 'c': list()}

    for index, letter in sorted_by_value:
        if letter == 'a':
            char_dict['a'].append((index, letter))

        if letter == 'b':
            char_dict['b'].append((index, letter))

        if letter == 'c':
            char_dict['c'].append((index, letter))

    left_pointer = -1
    right_pointer = len(s)

    residual = 0

    for char in char_dict.keys():
        for _ in range(k):
            left_difference = char_dict[char][0][0] - left_pointer
            right_difference = right_pointer - char_dict[char][-1][0]

            if left_difference < right_difference:
                left_most = char_dict[char].pop(0)

                left_pointer = max(left_pointer, left_most[0])

            elif left_difference > right_difference:
                right_most = char_dict[char].pop(-1)

                right_pointer = min(right_pointer, right_most[0])

            else:
                movement_from_left = left_pointer + 1
                movement_from_right = len(s) - right_pointer

                if movement_from_left > movement_from_right:
                    left_most = char_dict[char].pop(0)
                    left_pointer = max(left_pointer, left_most[0])

                elif movement_from_left < movement_from_right:
                    right_most = char_dict[char].pop(-1)    
                    right_pointer = min(right_pointer, right_most[0])

                else:
                    residual += 1

    print(left_pointer)
    print(right_pointer)
    movement_from_left = left_pointer + 1
    movement_from_right = len(s) - right_pointer
    print(movement_from_left)
    print(movement_from_right)

    if movement_from_left >= movement_from_right:
        movement_from_left += residual

    elif movement_from_left < movement_from_right:
        movement_from_right -= residual

    return movement_from_left + movement_from_right

result = minimum_k(s, k)
print(result)
print(result == accepted)